import React from 'react';
import { render, screen } from '@testing-library/react';
import Bees from './Bees';

describe('Bees', () => {
  test('should render without crashing', () => {
    render(<Bees />);
    expect(screen.getByTestId('BeesIcon')).toBeInTheDocument();
  });
  test('should render icon variant without crashing', () => {
    render(<Bees variant="icon" colorType="onDarkBg" />);
    expect(screen.getByTitle('Bees Icon')).toBeInTheDocument();
  });
  test('should render vertical variant without crashing', () => {
    render(<Bees variant="vertical" colorType="onDarkBg" />);
    expect(screen.getByTitle('Bees Vertical Logo')).toBeInTheDocument();
  });
});
